1	import { readdirSync, readFileSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	import { loadPacks, resolveDeclaredPacks, packEntryId, SHARED_SUBDIR, PACK_DIRECTORY_FILE } from '../engine/pack_loader/pack-registry.mjs';
5	import { relativeImports, resolveRelative, ENGINE_DIR_ROOTS } from '../engine/checks/helpers/module-imports.mjs';
6	import { migrationApplies, MIGRATIONS_SUBDIR } from '../engine/checks/helpers/active-migrations.mjs';
7	import { ENGINE_VERSION } from '../engine/version.mjs';
8	
9	// The vendor-set computation for the vendored mount (DESIGN.md): given a repo's
10	// pack declaration, the minimal corpus file set that repo persists under
11	// SHARED_SUBDIR — canon-relative paths, mirroring exactly what a future
12	// submodule mounted at that same root would place there. Always computed
13	// against the canon tree THIS module ships in — the nightly runs it from the
14	// home checkout, an on-demand refresh from the tree it just fetched — so the
15	// set and the content can never come from different snapshots.
16	const canonRoot = dirname(dirname(fileURLToPath(import.meta.url))); // <canon>/vendoring/ — canon-internal, never vendored (#385)
17	
18	// Re-exported for the writers (the nightly update pass, an on-demand refresh):
19	// the consumer-side root the set materializes under.
20	export { SHARED_SUBDIR };
21	
22	// The engine is discovered structurally, never listed file-by-file: the engine
23	// root vendors wholesale (a new engine file ships with no edit here). The list
24	// lives in the engine lib (engine/checks/helpers/module-imports.mjs) — the same
25	// surface the pack-independence barrier confines pack imports to, so "what a
26	// pack may import" and "what every consumer carries" can never drift apart —
27	// re-exported here as the vendor-set contract (DESIGN.md). engine/ carries no
28	// tests (they live in engine-tests/, mirroring its structure — #385), so the
29	// engine walk is a plain copy minus *.md — engine docs are canon-maintainer
30	// reference, read upstream when needed, while a pack's .md files are the
31	// payload and ride its directory below. A pack's tests live in the pack's own
32	// `test/` directory, and that whole directory is dropped: the name is the rule, so
