206	test('regression: the REAL canon tree vendors the WHOLE queue engine, .md included', async () => {
207	  const { readdirSync } = await import('node:fs');
208	  const { computeVendorSet } = await import('./compute-vendor-set.mjs');
209	  const { files } = await computeVendorSet(['basics', 'claudinite-tasks']);
210	  // WALKED, not listed: the queue engine has subdirectories now (the engine's own
211	  // built-in tasks), and a top-level listing would assert the directory name and
212	  // never look inside it — which is how the request task's `task.md` was dropped by
213	  // the blanket engine-.md rule while this test stayed green.
214	  const walk = (url, prefix) => readdirSync(url, { withFileTypes: true }).flatMap((e) => (
215	    e.isDirectory()
216	      ? walk(new URL(`${e.name}/`, url), `${prefix}${e.name}/`)
217	      : (e.name.endsWith('.test.mjs') ? [] : [`${prefix}${e.name}`])));
218	  const onDisk = walk(new URL('../packs/claudinite-tasks/queue/', import.meta.url), '');
219	  assert.ok(onDisk.length > 0, 'the queue engine directory must exist and be non-empty');
220	  assert.ok(onDisk.some((n) => n.includes('/')), 'the walk reaches inside the queue engine, not just its top level');
221	  for (const name of onDisk) {
222	    assert.ok(files.includes(`packs/claudinite-tasks/queue/${name}`),
223	      `packs/claudinite-tasks/queue/${name} is runtime-operational and must vendor — a mount missing it breaks the queue on every member`);
224	  }
225	});
