90	  return root;
91	}
92	
93	/**
94	 * Scratch git repo: `base` files committed on main, then a feature branch with
95	 * `changed` files committed on top (message `commitMsg`). Mirrors the runner's
96	 * real scoping model — merge-base with `main` — without needing a remote.
97	 */
98	export function makeRepo({ base = {}, changed = {}, commitMsg = 'change Refs #1', uncommitted = {} }) {
99	  const root = mkdtempSync(join(tmpdir(), 'claudinite-checks-'));
100	  cpSync(templateRepo(), root, { recursive: true });
101	  // `base` files belong in the commit `main` names, which the template's seed
102	  // commit is not — so they arrive as a commit on top of the copy and `main` moves
103	  // onto it. What a context reads is the merge-base with `main` and the range above
104	  // it, both of which that move reproduces exactly; the tree at the merge-base is
105	  // the same tree the one-commit seed had, README override included.
106	  if (Object.keys(base).length) {
107	    writeFiles(root, base);
108	    git(root, 'add', '-A');
109	    git(root, 'commit', '-q', '-m', 'seed');
110	    git(root, 'branch', '-f', 'main', 'HEAD');
111	  }
112	  if (Object.keys(changed).length) {
113	    writeFiles(root, changed);
114	    git(root, 'add', '-A');
115	    git(root, 'commit', '-q', '-m', commitMsg);
116	  }
117	  writeFiles(root, uncommitted);
118	  return root;
119	}
120	
121	export function deletePath(root, path, commitMsg = 'delete Refs #1') {
122	  git(root, 'rm', '-q', path);
123	  git(root, 'commit', '-q', '-m', commitMsg);
124	}
125	
126	/**
127	 * Scratch session transcript (Claude Code JSONL) for conversation-surface
128	 * rules. Lives outside any scratch repo so it never appears in ctx.files.
129	 *
130	 * `subagents` maps an agent id to that subagent's own entries, laid out where
131	 * Claude Code puts them — `<session>/subagents/agent-<id>.jsonl` beside the
132	 * session file — so a test can exercise a reader over the whole session.
133	 */
134	export function makeTranscript(entries, subagents = {}) {
135	  const dir = mkdtempSync(join(tmpdir(), 'claudinite-transcript-'));
136	  const path = join(dir, 'session.jsonl');
137	  const jsonl = (es) => es.map((e) => JSON.stringify(e)).join('\n') + '\n';
138	  writeFileSync(path, jsonl(entries));
139	  const agentDir = join(dir, 'session', 'subagents');
140	  for (const [id, agentEntries] of Object.entries(subagents)) {
141	    mkdirSync(agentDir, { recursive: true });
142	    writeFileSync(join(agentDir, `agent-${id}.jsonl`), jsonl(agentEntries));
143	  }
144	  return { path, cleanup: () => removeTree(dir) };
145	}
146	
147	// One declared check, by rule id, out of a pack's or skill's declared-checks.json
148	// — the test-side counterpart to the registry's structural discovery, so a test
149	// proves the same compiled rule object the runner runs. `dir` is repo-relative
150	// (`packs/aws-sam`). An unknown id is the test's bug, not a silent undefined.
151	export function declaredCheck(dir, id) {
152	  const rules = loadDeclaredChecks(join(repoRoot, dir));
153	  const rule = rules.find((r) => r.id === id);
154	  if (!rule) throw new Error(`${dir}/declared-checks.json declares no rule "${id}" (it has: ${rules.map((r) => r.id).join(', ')})`);
155	  return rule;
156	}
157	
158	// Kept as the name every fixture already calls; the retry it exists for now lives
159	// in one place, with the whole story of why (engine/remove-tree.mjs).
160	export function cleanup(root) {
161	  removeTree(root);
162	}
163	
164	/**
165	 * Table-driven rule testing — a test case is its data: a repo shape in, the
166	 * expected findings out. Each entry in `clean` / `flagged` registers one
167	 * node:test; makeRepo / buildContext / try-finally-cleanup live here so the
168	 * test file reads as fixture -> expectation and nothing else.
169	 *
170	 *   ruleTester(rule, {
171	 *     clean: {
172	 *       'the safe state stays silent': { files: { 'a.txt': 'ok\n' } },
173	 *     },
174	 *     flagged: {
175	 *       'the hazard is reported at its line': {
176	 *         files: { 'a.txt': 'bad\n' },
177	 *         at: [{ file: 'a.txt', line: 1, what: /bad/ }],
178	 *       },
179	 *     },
180	 *   });
181	 *
182	 * A case's repo shape: `files` commits on the feature branch (makeRepo
183	 * `changed`, under `commitMsg` where the rule judges the message), `base` on
184	 * main, `uncommitted` stays untracked; `mode` defaults to 'all'. The rule is
185	 * invoked through `runRule`, the same dispatch seam the runner uses, so a
186	 * work-scoped rule gets its fluent surface here exactly as it does in a run.
187	 * A flagged case's `at` lists every expected finding in engine
188	 * order; each expectation may pin `file` (exact), `line` (exact — a finding
189	 * with no line anchor carries the explicit `line: null`), `severity` (exact),
190	 * and `what` / `fix` (regexes). Keys an expectation omits are not judged.
191	 */
192	export function ruleTester(rule, { clean = {}, flagged = {} }) {
193	  const runCase = (c) => {
194	    const root = makeRepo({
195	      base: c.base ?? {}, changed: c.files ?? {}, uncommitted: c.uncommitted ?? {},
196	      ...(c.commitMsg ? { commitMsg: c.commitMsg } : {}),
