251	// general escape hatch for arbitrary code in a record.
252	//
253	// SEEDS NOTHING AND DROPS NOTHING: entry objects keep their config, answers and
254	// order; only the id token changes. Idempotent — a repo already on `local/` is a
255	// no-op — and it patches the parsed declaration back through JSON.stringify with
256	// the same 2-space shape every other declaration writer here uses.
257	export async function applyLocalDeclarationNormalization(migration, { read, write, exists }) {
258	  if (!migration.normalizeLocalDeclarations) return [];
259	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
260	  const file = await declarationFile(read);
261	  if (file == null) return [];
262	  const raw = await read(file);
263	  let config;
264	  try { config = JSON.parse(raw); } catch { return []; }
265	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
266	  if (!Array.isArray(config.packs)) return [];
267	
268	  const done = [];
269	  const packs = [];
270	  for (const entry of config.packs) {
271	    const id = typeof entry === 'string' ? entry : entry?.id;
272	    if (typeof id !== 'string' || id.startsWith(LOCAL_DECL)) { packs.push(entry); continue; }
273	    let bare = id.startsWith(LEGACY_LOCAL_DECL) ? id.slice(LEGACY_LOCAL_DECL.length) : null;
274	    if (bare === null) {
275	      // A bare id: local only if this repo actually carries that pack. Both mount
276	      // shapes are checked, because a repo mid-relocation may hold either.
277	      const isLocal = (await exists(`.claudinite/local/packs/${id}/pack.mjs`))
278	        || (await exists(`.claudinite/local_packs/${id}/pack.mjs`));
279	      if (!isLocal) { packs.push(entry); continue; }
280	      bare = id;
281	    }
282	    const token = `${LOCAL_DECL}${bare}`;
283	    packs.push(typeof entry === 'string' ? token : { ...entry, id: token });
284	    done.push(`${file}: ${id} -> ${token}`);
285	  }
286	  if (done.length) await write(file, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
287	  return done;
288	}
289	
290	// The declaration tokens this op normalizes to and from. Stated here rather than
291	// imported from the pack registry: this module is the write side a consumer runs
292	// out of its own mount, and the two prefixes are the whole of what it needs.
293	const LOCAL_DECL = 'local/';
294	// @legacy-tolerance advisory:legacy-shape-in-use retire:#1640
295	const LEGACY_LOCAL_DECL = 'local_packs/';
296	
297	// Write side — "the packs this repo declares have been renamed": rewrite each
298	// `packs` entry whose id is a legacy spelling to the id that pack carries today.
299	// The ids come from the engine's own rename map, never from the record, so a future
300	// rename needs no new op and no record restating what the loader already knows.
301	//
302	// STRUCTURAL, NOT TEXTUAL, and that is the whole point of it. The first attempt at
303	// this was a regex over the declaration, anchored on `"packs": [` so it could not
304	// wander into a member's own `{ "from": "core" }` barrier rule. It could not wander
305	// anywhere at all: a real packs array holds entry objects with nested arrays
306	// (`{ "id": "barriers", "via": ["basics"] }`), the anchor could not cross a nested
307	// `]`, and every element after the first such object was invisible to it. Parsing
308	// removes both failures at once — the `packs` array is the only thing read, so a
309	// same-named key anywhere else in the file is never even seen (#1041).
310	//
311	// SEEDS NOTHING AND DROPS NOTHING, like the local-declaration normalization beside
312	// it: entry objects keep their config, answers, `via` and order; only the id token
313	// changes. A LOCAL declaration is skipped — that namespace is the repo's, so a local
314	// pack sharing a canon pack's old name is not this op's business. Idempotent, so a
315	// repo already converged is a no-op, and it patches the parsed declaration back with
316	// the same 2-space shape every other declaration writer here uses.
317	// Two entries that were different packs and are now the same one. A rename can
318	// merge two ids into one (a pack absorbed into another), and every member carrying
319	// the absorbed pack carries the absorbing one too when the first `requires` the
320	// second — so the collision is not an edge case there, it is every member.
321	//
322	// Dropping either side would drop what a member wrote: `config` answers it gave at
323	// adoption, `rules` severities it chose, `accept` entries standing against findings
324	// that would otherwise come back. So the two are MERGED. The survivor is the entry
325	// that appeared first, and its own values win a key conflict — the absorbed entry
326	// fills only what the survivor does not say. Arrays (`accept`, `rules`, `via`)
327	// concatenate, dropping an element the survivor already carries verbatim. An object
328	// absorbed into a plain-string entry promotes the survivor to an object: a string
329	// entry carries an id and nothing else, so keeping the string would be the one shape
330	// that silently discards the other side.
331	export function mergeDeclarationEntries(survivor, absorbed) {
332	  if (typeof absorbed === 'string') return survivor;
333	  const base = typeof survivor === 'string' ? { id: survivor } : { ...survivor };
334	  for (const [key, value] of Object.entries(absorbed)) {
335	    if (key === 'id') continue;
336	    const have = base[key];
337	    if (have === undefined) { base[key] = value; continue; }
338	    if (Array.isArray(have) && Array.isArray(value)) {
339	      const seen = new Set(have.map((v) => JSON.stringify(v)));
340	      base[key] = [...have, ...value.filter((v) => !seen.has(JSON.stringify(v)))];
341	      continue;
342	    }
343	    if (have && value && typeof have === 'object' && typeof value === 'object'
344	      && !Array.isArray(have) && !Array.isArray(value)) {
345	      base[key] = { ...value, ...have };
346	    }
347	    // Two scalars that disagree: the survivor's stands. It is the entry the member
348	    // wrote for the pack that still exists under its own name.
349	  }
350	  // `via` says which packs pulled this one in, and an absorbed pack's `via` can name
351	  // the very pack that absorbed it — leaving the survivor claiming it was required by
352	  // itself. Drop that, and where nothing but the id survives, write the entry back as
353	  // the bare string a member declaring a plain pack has.
354	  if (Array.isArray(base.via)) {
355	    const via = base.via.filter((v) => v !== base.id);
356	    if (via.length) base.via = via; else delete base.via;
357	  }
358	  return Object.keys(base).length === 1 ? base.id : base;
359	}
360	
361	// An ABSORBED pack's entry, reshaped for the pack that is about to swallow it.
362	// Two things a plain id rename cannot get right on its own:
363	//
364	//   CONFIG COLLIDES. Both entries carry a flat `config`, and the merge below
365	//   spreads one over the other — so an absorbed `{ rules: [...] }` would land as
366	//   the survivor's own `config.rules`, a key the survivor may already mean
367	//   something else by. Nesting it under the absorbed pack's own id keeps the
368	//   parameters saying whose they are, which is also what the survivor's code then
369	//   reads.
370	//   ANSWERS OUTLIVE THEIR QUESTION. An answer is recorded against a question the
371	//   absorbed pack declared; the survivor does not declare it, so the answer
372	//   becomes an interview-hygiene finding the owner cannot act on. The record names
373	//   the ids it drops rather than dropping every answer, because a RENAME (as
374	//   opposed to an absorption) keeps asking its questions.
375	//
376	// Declared per record — `absorbedPackConfig: [{ id, dropAnswers? }]` — never
377	// derived from the rename map, which cannot tell an absorption from a rename.
378	function reshapeAbsorbed(entry, spec) {
379	  if (typeof entry === 'string' || entry === null || typeof entry !== 'object') return entry;
380	  const next = { ...entry };
381	  if (next.config !== undefined && next.config !== null) next.config = { [spec.id]: next.config };
382	  const drop = spec.dropAnswers ?? [];
383	  if (drop.length && next.answers && typeof next.answers === 'object') {
384	    const kept = Object.fromEntries(Object.entries(next.answers).filter(([k]) => !drop.includes(k)));
385	    if (Object.keys(kept).length) next.answers = kept; else delete next.answers;
386	  }
387	  return next;
388	}
389	
390	export async function applyPackRenames(migration, { read, write }) {
391	  if (!migration.renameDeclaredPacks) return [];
392	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
393	  const file = await declarationFile(read);
394	  if (file == null) return [];
395	  const raw = await read(file);
396	  let config;
397	  try { config = JSON.parse(raw); } catch { return []; }
398	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
399	  if (!Array.isArray(config.packs)) return [];
400	
401	  const done = [];
402	  const absorbed = new Map((migration.absorbedPackConfig ?? []).map((s) => [s.id, s]));
403	  const renamed = config.packs.map((raw) => {
404	    const id = typeof raw === 'string' ? raw : raw?.id;
405	    if (typeof id !== 'string' || id.startsWith(LOCAL_DECL) || id.startsWith(LEGACY_LOCAL_DECL)) return raw;
406	    const to = RENAMED_PACKS[id];
407	    if (to === undefined) return raw;
408	    const spec = absorbed.get(id);
409	    const entry = spec ? reshapeAbsorbed(raw, spec) : raw;
410	    done.push(`${file}: ${id} -> ${to}`);
411	    return typeof entry === 'string' ? to : { ...entry, id: to };
412	  });
413	
414	  // Collapse what the rename made duplicates. Position is the first occurrence's,
415	  // so an id already in the array keeps its place rather than moving to where the
416	  // absorbed entry sat.
417	  const at = new Map();
418	  const packs = [];
419	  for (const entry of renamed) {
420	    const id = typeof entry === 'string' ? entry : entry?.id;
421	    if (typeof id !== 'string' || !at.has(id)) {
422	      if (typeof id === 'string') at.set(id, packs.length);
423	      packs.push(entry);
424	      continue;
425	    }
426	    const i = at.get(id);
427	    packs[i] = mergeDeclarationEntries(packs[i], entry);
428	    done.push(`${file}: merged a second "${id}" entry into the first`);
429	  }
430	
431	  if (done.length) await write(file, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
432	  return done;
433	}
434	
435	
436	// Write side — "this top-level setting belonged to a pack all along": for each declared
437	// `{ key, pack }`, lift that key off the top level of the member's declaration and onto
438	// that pack's entry `config`.
439	//
440	// A NAMED OP rather than a `rewrite`, for the reason every declaration op here exists:
441	// a rewrite replaces literal text, and the target is a key nested inside an object
442	// inside the `packs` ARRAY, which no anchored pattern can reach across — a regex
443	// anchored on `"packs": [` cannot cross the first entry object's nested `]`, so every
444	// entry after it is invisible. Parsing is what makes the edit reliable, and it keeps
445	// key ORDER intact for everything it does not touch, because this is a file people read.
446	//
447	// THE PACK MUST BE DECLARED for the setting to mean anything. Where it is not, the key
448	// is DROPPED rather than moved: a parameter for a pack the repo does not run governed
449	// nothing, and inventing an entry to hold it would activate a pack nobody asked for.
450	// Where the entry already carries its own value for the key, that value STANDS and the
451	// retired one is dropped — the pack entry is the current spelling, so a member that has
452	// already answered there is not overruled by a key it forgot to delete.
453	//
454	// Idempotent by construction: every step is "if the retired key is there", so a second
455	// run finds nothing and writes nothing.
456	export async function applyPackOwnedSettingMoves(migration, { read, write }) {
457	  if (!migration.movePackOwnedSettings?.length) return [];
458	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
459	  const file = await declarationFile(read);
460	  if (file == null) return [];
461	  const raw = await read(file);
462	  let config;
463	  try { config = JSON.parse(raw); } catch { return []; }
464	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
465	
466	  const done = [];
467	  let next = config;
468	  for (const { key, pack } of migration.movePackOwnedSettings) {
469	    if (next[key] === undefined) continue;
470	    const packs = Array.isArray(next.packs) ? [...next.packs] : [];
471	    const at = packs.findIndex((e) => (typeof e === 'string' ? e : e?.id) === pack);
472	    if (at === -1) {
473	      const dropped = { ...next };
474	      delete dropped[key];
475	      next = dropped;
476	      done.push(`${file}: dropped the retired top-level "${key}" — "${pack}" is not declared here, so it governed nothing`);
477	      continue;
478	    }
479	    const entry = typeof packs[at] === 'string' ? { id: packs[at] } : { ...packs[at] };
480	    if (entry.config?.[key] === undefined) {
481	      entry.config = { ...entry.config, [key]: next[key] };
482	      done.push(`${file}: "${key}" -> the "${pack}" pack entry's config`);
483	    } else {
484	      done.push(`${file}: dropped the retired top-level "${key}" — the "${pack}" entry already declares it`);
485	    }
486	    packs[at] = entry;
487	    // Assigned rather than re-spread onto a fresh object, so `packs` keeps the position
488	    // it already had in the file instead of jumping to the end.
489	    const moved = { ...next };
490	    moved.packs = packs;
491	    delete moved[key];
492	    next = moved;
493	  }
494	  if (done.length) await write(file, `${JSON.stringify(next, null, 2)}\n`);
495	  return done;
496	}
497	
498	// Write side — "this member's settings file moves to its new name and its new
499	// shape" (#1252). The one op that RENAMES the declaration, which is why it is an op
500	// rather than four `rewrite`s: a rewrite replaces literal text, and no two members
501	// share a literal here; a materialization writes a whole template, which would
502	// clobber every project's own declaration.
503	//
504	// What it does, in the order that keeps a half-applied run readable:
505	//   1. moves `.claudinite-checks.json` to `.claudinite-settings.json` (git sees a
506	//      rename, so the file's history follows it);
507	//   2. lifts the retired `claudinite` block's `engineVersion` to the top level and
508	//      its `packVersions` onto the entry of each pack they price, dropping any key
509	//      no entry names — a version for a pack the declaration does not carry prices
510	//      nothing, and inventing an entry for it would activate a pack nobody declared;
511	//   3. turns `maintenance.delivery: review` into
512	//      `dailyClaudiniteUpdatesRequirePrReview: true` and drops the block — including
513	//      `mechanism`, whose only rival was deleted in #768 Phase 5, so it had exactly
514	//      one possible answer for every member that could still ask;
515	//   4. renames `taskScheduler.endpoints` to `agenticTaskInvocationEndpoints`.
516	//
517	// IDEMPOTENT BY CONSTRUCTION: every step is stated as "if the retired shape is
518	// there", so a second run finds nothing and writes nothing. It reads the member's
519	// OWN file and rewrites only the keys it names — a project's rules, accept entries,
520	// pack config and answers pass through untouched, and key ORDER is preserved for
521	// everything it does not move, because this is a file people read.
522	export async function applySettingsReshape(migration, { read, write, move, exists }) {
523	  if (!migration.reshapeSettings) return [];
524	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
525	  const file = await declarationFile(read);
526	  if (file == null) return [];
527	  const raw = await read(file);
528	  let config;
529	  try { config = JSON.parse(raw); } catch { return []; }
530	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
531	
532	  const done = [];
533	
534	  // 1. The name. Moved before anything is written, so the write below lands on the
535	  //    renamed file and git records one rename rather than a delete and an add.
536	  if (file === LEGACY_SETTINGS_FILE) {
537	    if (await exists(SETTINGS_FILE)) return [];     // both names present — a repair no record should guess at
538	    await move(LEGACY_SETTINGS_FILE, SETTINGS_FILE);
539	    done.push(`${LEGACY_SETTINGS_FILE} -> ${SETTINGS_FILE}`);
540	  }
541	
542	  // 2. The versions, onto the shape that holds them now.
543	  let next = config;
544	  if (next[LEGACY_STAMP_KEY] !== undefined) {
545	    const { engineVersion, packVersions } = installedVersions(next);
546	    next = withInstalledVersions(next, { engineVersion, packVersions });
547	    delete next[LEGACY_STAMP_KEY];
548	    done.push(`${SETTINGS_FILE}: engineVersion and per-pack versions lifted out of "${LEGACY_STAMP_KEY}"`);
549	  }
550	
551	  // 3. The delivery override. Only `review` carries an intent worth keeping; every
552	  //    other value said what the absent key now says.
553	  if (next.maintenance !== undefined) {
554	    const delivery = String(next.maintenance?.delivery ?? '').trim();
555	    const { maintenance, ...rest } = next;
556	    next = rest;
557	    if (delivery === 'review' || delivery === 'pr') {
558	      next.dailyClaudiniteUpdatesRequirePrReview = true;
559	      done.push(`${SETTINGS_FILE}: maintenance.delivery "${delivery}" -> dailyClaudiniteUpdatesRequirePrReview: true`);
560	    } else {
561	      done.push(`${SETTINGS_FILE}: dropped the retired "maintenance" block`);
562	    }
563	  }
564	
565	  // 4. The endpoint map's name.
566	  const scheduler = next.taskScheduler;
567	  if (scheduler && typeof scheduler === 'object' && !Array.isArray(scheduler)
568	      && scheduler[LEGACY_ENDPOINTS_KEY] !== undefined && scheduler[ENDPOINTS_KEY] === undefined) {
569	    const { [LEGACY_ENDPOINTS_KEY]: endpoints, ...restScheduler } = scheduler;
570	    next = { ...next, taskScheduler: { [ENDPOINTS_KEY]: endpoints, ...restScheduler } };
571	    done.push(`${SETTINGS_FILE}: taskScheduler.${LEGACY_ENDPOINTS_KEY} -> ${ENDPOINTS_KEY}`);
572	  }
573	
574	  if (done.length) await write(SETTINGS_FILE, `${JSON.stringify(next, null, 2)}\n`);
575	  return done;
576	}
577	
578	// EVERY write op a record can carry, in the order a run applies them, over one
579	// injected io. Both callers — the standalone applier and the engine update flow —
580	// go through this, so an op added to the vocabulary cannot reach one and miss the
581	// other: that omission is silent (the record simply does nothing on that path) and
582	// is exactly what a member would never notice.
583	
584	// Write side — "a task's cadence is one of its own conditions"
585	// (docs/PRINCIPLES.md, #1725): fold the retired `frequency` of every local pack's task.json
586	// into its `preconditions`, as anchored text. A NAMED CODEMOD like the declaration
587	// normalization above: which files carry the field is the repo's own disk.
588	// The record declares `updateTaskSchedulingFields: true`; the rewrite ships with the
589	// engine (task-declarations-to-json.mjs) and is the same one the CLI runs.
590	//
591	// Needs the directory listing beyond the classic io; a caller without it rewrites
592	// nothing rather than half-rewriting, and both retired shapes keep working at the
593	// door until a worker that can do the step runs.
594	export async function applyTaskSchedulingFields(migration, io) {
595	  if (!migration.updateTaskSchedulingFields) return [];
596	  if (typeof io.listDir !== 'function') return [];
597	  if (migration.appliesTo && !(await migration.appliesTo(io.read))) return [];
598	  return updateTaskSchedulingFields(taskDirsWithJson([LOCAL_PACK_ROOT], io), io);
599	}
600	
601	export async function applyMigration(migration, io) {
602	  const applied = [];
603	  applied.push(...(await applyFileAliases(migration, io)));
604	  applied.push(...(await applyMaterializations(migration, io)));
605	  applied.push(...(await applyRewrites(migration, io)));
606	  applied.push(...(await applyPackDeclarations(migration, io)));
607	  applied.push(...(await applyLocalDeclarationNormalization(migration, io)));
608	  applied.push(...(await applyTaskSchedulingFields(migration, io)));
609	  applied.push(...(await applyPackRenames(migration, io)));
610	  // AFTER the renames: a setting moving onto a pack's entry has to find that entry
611	  // under the id the pack carries TODAY, which is what the rename above just settled.
612	  applied.push(...(await applyPackOwnedSettingMoves(migration, io)));
613	  // LAST: every op above writes to whichever name the member still carries, and this
614	  // is the one that changes which name that is.
615	  applied.push(...(await applySettingsReshape(migration, io)));
616	  return applied;
617	}
618	
619	// THE `agentic` FIELD IS RETIRED (#768 Phase 5), and its successor is `applyStage`
620	// below. A record used to carry `agentic: { model, instructions }` — member-side
621	// adaptation no script could do — and baselining's code-work read it to decide whether
622	// a pending note needed an agent stage, holding the member's stamp until one ran.
623	//
624	// What the successor drops is the MODEL knob. Which model runs a session is the
625	// scheduler's answer (packs/claudinite-tasks/model-map.mjs, off the task declaration), and
626	// a record reaching around it to name its own was a second authority over the same
627	// fact. What a record legitimately knows is narrower and is all `applyStage` asks
628	// for: whether its change needs a session at all, and what that session must do.
629	//
630	// The field is not merely ignored, it is REJECTED. An ignored field on a record
631	// someone writes in good faith is work that silently never happens; the whole reason
632	// the note existed was that skipping such work quietly is a correctness risk (#405).
633	// Failing at load turns a stale or hopeful note into an error with a fix attached.
634	export function assertNoAgenticNote(m) {
635	  if (m?.agentic === undefined || m?.agentic === null) return;
636	  throw new Error(`migration ${m.id}: the "agentic" field was retired in #768 Phase 5 and is no longer run. `
637	    + 'Declare `applyStage: { why, instructions }` instead — same intent, without the model knob, which the '
638	    + 'scheduler owns. Engine records may not carry it at all (DESIGN §5); a pack record may.');
639	}
640	
641	// THE `applyStage` FIELD: this record's change needs a session on the member.
642	//
643	// It exists because the alternative was worse. The pack flow used to decide the
644	// apply stage from its VERSION PLAN — "any pack version moved" — which is a fact
645	// about the CANON, while the stage exists for a fact about the MEMBER: the pack's
646	// new rules met content the canon has never seen. Since a record can only reach an
647	// up-to-date member if its pack's manifest version bumps, and every bump fired the
648	// stage, a purely mechanical migration — a regex rewrite, a declaration seed — could
649	// not be shipped without spending an agent session on every member in the fleet
650	// (#798). The record's author knows which of the two kinds they wrote; a version
651	// number never can.
652	//
653	// SHAPE, VALIDATED AT LOAD for the same reason the retired field is rejected there:
654	// a record whose declaration is malformed must fail where it is written, not go
655	// quietly unread by the flow that would have acted on it.
656	//
657	//   - `why` (required, non-empty string) — what the session is for, in the PR and in
658	//     the log. The terminal vocabulary insists every non-green end be explainable
659	//     (the update flows' terminal vocabulary), and this is the sentence for this one.
660	//   - `instructions` (optional string) — appended to the standing brief. The standing
661	//     brief is policy that holds for every apply stage; this is what only this record
662	//     knows, and without it the declaration would be a bare boolean that tells the
663	//     session nothing about the change that summoned it.
664	//
665	// ENGINE RECORDS MAY NOT CARRY IT. "No agentic work in the engine flow. Ever."
666	// (DESIGN §5) — and the flow is read off where the record LIVES, so this is checked
667	// against the same structural classifier and cannot be misdeclared.
668	export function assertApplyStageDeclaration(m) {
669	  const declared = m?.applyStage;
670	  if (declared === undefined || declared === null) return;
671	  const bad = (what) => { throw new Error(`migration ${m.id}: ${what}`); };
672	  if (m.dir && flowOf(m.dir).flow !== 'pack') {
673	    bad('only a PACK record may declare "applyStage" — the engine update flow has no agentic lane (DESIGN §5). '
674	      + 'If the change needs a session on each member, it belongs to the pack whose rules it changes.');
675	  }
676	  if (typeof declared !== 'object' || Array.isArray(declared)) {
677	    bad('"applyStage" must be an object `{ why, instructions }`, not a bare flag — a stage nobody can explain '
678	      + 'is one nobody will trust the next time it fires.');
679	  }
680	  if (typeof declared.why !== 'string' || declared.why.trim() === '') {
681	    bad('"applyStage.why" must be a non-empty string saying what the session is for; it is what the PR and the log report.');
682	  }
683	  if (declared.instructions !== undefined && typeof declared.instructions !== 'string') {
684	    bad('"applyStage.instructions" must be a string — it is appended verbatim to the apply-stage brief.');
685	  }
686	}
