526	    // Normalize one to-entry: '*', '<folder>/*', or a folder prefix. Null = error.
527	    const parseTarget = (t) => {
528	      if (t === '*') return '*';
529	      const s = t.replace(/\\/g, '/');
530	      const glob = s.endsWith('/*');
531	      const p = normPrefix(glob ? s.slice(0, -2) : s);
532	      if (p === '' || p.includes('*')) {
533	        errors.push({ what: `${at}: "to" must name a real subfolder, a "<folder>/*" glob, or "*"`, fix: 'name the barred folder, "<folder>/*" for its child directories, or "*" for isolation' });
534	        return null;
535	      }
536	      return glob ? `${p}/*` : p;
537	    };
538	
539	    const mk = (froms, targets) => ({ froms, targets, siblings, scope, allow, carve, exceptions, matchNames, alsoMatchNames, matchUniqueFilenames, reason });
