541	    if (Array.isArray(spec.between)) {
542	      if (spec.between.length !== 2 || spec.between.some((s) => typeof s !== 'string' || !s.trim() || s.includes('*'))) {
543	        errors.push({ what: `${at} "between" must be two folder paths`, fix: 'use "between": ["clientDir", "serverDir"] — no wildcards' });
544	        return;
545	      }
546	      const [a, b] = spec.between.map(normPrefix);
547	      if (a === '' || b === '') {
