595	    for (let i = 0; i < exceptions.length; i++) {
596	      const e = exceptions[i];
597	      if (!(e.path === f.file || (e.path.endsWith('/') && f.file.startsWith(e.path)))) continue;
598	      if (!e.to) { used[i][0] = true; return false; }
599	      for (let j = 0; j < e.to.length; j++) {
600	        if (under(f.resolved, e.to[j])) { used[i][j] = true; return false; }
601	      }
602	    }
603	    return true;
604	  });
605	  const stale = [];
606	  exceptions.forEach((e, i) => {
607	    if (!e.to) { if (!used[i][0]) stale.push({ path: e.path, to: null }); }
