827	      for (const kid of kids) scanEdge({ ...edge, froms: [kid] });
828	      continue;
829	    }
830	    scanEdge(edge);
831	  }
832	  return { findings: out, stale: staleAll };
833	}
834	
835	// Emit a spec/shape error as a blocking finding pinned at the settings file.
836	export function specFinding(rule, { what, fix }) {
837	  return finding(rule, {
838	    file: '.claudinite-settings.json',
839	    line: null,
840	    what: `barriers config: ${what}`,
841	    why: 'a malformed barrier declaration silently enforces nothing',
842	    fix,
843	    severity: 'blocking',
844	  });
845	}
846	
847	// A stale reviewed exception (it matched no crossing) means the coupling it
848	// excused is gone — surface it so paid-down debt gets pruned. Judged only by the
849	// caller on a whole-repo sweep with a clean config (a --changed run sees only
850	// part of the findings; a config error means the scan itself was incomplete).
851	export function staleFindings(stale, rule) {
852	  return stale.map((s) => specFinding(rule, {
853	    what: `exception for "${s.path}"${s.to ? ` → "${s.to}"` : ''} matched nothing — the coupling it excused is gone`,
854	    fix: `remove the stale exception${s.to ? ' (or the stale "to" item)' : ''} from the rule's "except"`,
855	  }));
856	}
