1	#!/usr/bin/env node
2	// Bring a repo's task declarations up to the current scheduling vocabulary: the
3	// retired `frequency` field (docs/PRINCIPLES.md, #1725) folded into
4	// `preconditions` as the cadence term it always meant, and the `trigger` its
5	// conditions already implied stated outright. Patched as ANCHORED TEXT, never
6	// re-serialized — a member's task.json is its author's, and a round-trip would
7	// rewrite its layout while nothing failed.
8	//
9	// Two callers. The `task-cadence-terms` migration record runs this against a
10	// member's OWN local packs on its nightly update, through the registry's io
11	// capabilities, so a member converges without anyone remembering to; and the CLI
12	// below rewrites a checkout by hand — the canon's own packs, or a member that
13	// wants it done sooner:
14	//
15	//   node engine/migrations/task-declarations-to-json.mjs [--root <repo>] [<task dir>…]
16	
17	import { existsSync, readdirSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
18	import { dirname, join, relative, posix } from 'node:path';
19	import { pathToFileURL } from 'node:url';
20	
21	export const TASK_JSON = 'task.json';
22	
23	// The pack roots a checkout's tasks live under. A member's own are the local
24	// packs; the canon also carries the shared packs at the repo root.
25	export const LOCAL_PACK_ROOT = '.claudinite/local/packs';
26	export const CANON_PACK_ROOT = 'packs';
27	
28	// The io over a real checkout — the same capability names the migration
29	// registry's callers build, so the record and the CLI run one rewrite.
30	export function checkoutIo(root) {
31	  const abs = (p) => join(root, p);
32	  return {
33	    exists: (p) => existsSync(abs(p)),
34	    read: (p) => (existsSync(abs(p)) ? readFileSync(abs(p), 'utf8') : null),
35	    write: (p, text) => { mkdirSync(dirname(abs(p)), { recursive: true }); writeFileSync(abs(p), text); },
36	    listDir: (p) => { try { return readdirSync(abs(p)); } catch { return null; } },
37	  };
38	}
39	
40	// --- the retired `frequency` field --------------------------------------------
41	
42	// What the field always meant, as the condition that now says it — or null for
43	// `manual`, which meant no schedule and adds no term. The one mapping the
44	// contract's door reads (`cadenceTermFor` in packs/claudinite-tasks/calendar.mjs),
45	// spelled again here because the engine imports no pack; the engine test pins the
46	// two to each other over every accepted value.
47	const cadenceTermFor = (frequency) => (frequency === 'manual' ? null : `due:${frequency}`);
48	
49	// The field wherever it sits: on a line of its own (nearly every declaration's
50	// layout) or inline in a one-line object. The commas
51	// around it are captured so the patch keeps exactly the separators the file needs.
52	const FREQUENCY_FIELD = /(,[ \t]*)?"frequency"[ \t]*:[ \t]*"([^"]*)"([ \t]*,)?/;
53	const PRECONDITIONS_ARRAY = /"preconditions"[ \t]*:[ \t]*\[([^\]]*)\]/;
54	// The same field with its separators, for dropping it whole (`withoutField`).
55	const PRECONDITIONS_FIELD = /(,[ \t]*)?"preconditions"[ \t]*:[ \t]*(\[[^\]]*\])([ \t]*,)?/;
56	
57	// Patch one task.json's text: the field goes, the cadence term leads the
58	// `preconditions` list (created in the field's own place where the file stated
59	// none), a `none` beside it drops, and the array keeps its own layout — inline or
60	// one entry per line at its own indent. Returns `{ text, term, frequency }`, or
61	// null where there is no field or where the patch would leave the file unparsable
62	// (the file is then left alone; the contract reports it as it is).
63	export function retireFrequencyText(source) {
64	  const text = String(source ?? '');
65	  const field = FREQUENCY_FIELD.exec(text);
66	  if (!field) return null;
67	  const frequency = field[2];
68	  const term = cadenceTermFor(frequency);
69	  const array = PRECONDITIONS_ARRAY.exec(text);
70	
71	  let out;
72	  if (array) {
73	    let stated;
74	    try { stated = JSON.parse(`[${array[1]}]`); } catch { return null; }
75	    if (!stated.every((e) => typeof e === 'string')) return null;
76	    const kept = stated.filter((e) => e.trim() !== 'none');
77	    const terms = term === null || kept.includes(term) ? kept : [term, ...kept];
78	    if (terms.length === 0) {
79	      // `manual` with nothing beside it: no schedule, which a declaration says by
80	      // stating no "preconditions" at all — both fields go.
81	      out = withoutField(withoutField(text, PRECONDITIONS_FIELD), FREQUENCY_FIELD);
82	      try { JSON.parse(out); } catch { return null; }
83	      return { text: out, term, frequency };
84	    }
85	    const multiline = array[1].includes('\n');
86	    const itemIndent = multiline ? (/\n([ \t]*)"/.exec(array[1])?.[1] ?? '    ') : null;
87	    const closeIndent = multiline ? (/\n([ \t]*)$/.exec(array[1])?.[1] ?? '  ') : null;
88	    const rendered = multiline
89	      ? `"preconditions": [\n${terms.map((t) => `${itemIndent}${JSON.stringify(t)}`).join(',\n')}\n${closeIndent}]`
90	      : `"preconditions": [${terms.map((t) => JSON.stringify(t)).join(', ')}]`;
91	    out = text.replace(PRECONDITIONS_ARRAY, rendered);
92	    out = withoutField(out, FREQUENCY_FIELD);
93	  } else if (term === null) {
94	    // `manual` and no list: the field alone goes, and the declaration states nothing.
95	    out = withoutField(text, FREQUENCY_FIELD);
96	  } else {
97	    // The field's own place becomes the list, its separators kept: a one-entry
98	    // list on its own lines where the field had a line, inline where it was inline.
99	    const [whole, leading = '', , trailing = ''] = field;
