  for (const r of [...carriers.rules, ...carriers.guidelines]) if (r.slug) ensureFile(r.slug, `rule "${r.trigger}"`);
  for (const s of carriers.skills) if (io.exists(s.file)) ensureFile(s.name, `skill ${s.name}`);
  for (const c of carriers.checks) ensureFile(idOfFile(fileOfId(c.id)), `check ${c.id}`);
  for (const t of carriers.tasks) ensureFile(t.id, `task ${t.id}`);
