export function parseReferencesDoc(text) {
  const out = [];
  const lines = String(text ?? '').split('\n');
  let cur = null;
  lines.forEach((line, i) => {
    const m = /^\s*-\s+\*\*\(([^)]+)\)\*\*\s*(.*)$/.exec(line);
    if (m) {
      cur = { key: m[1].trim(), text: m[2].trim(), line: i + 1 };
