  out = out.replace(/(?:^|(?<=\s))“[^”\n]{12,}”(?=[\s.,;:)]|$)/g, '(quote dropped)');
  if (publicCanon) {
    out = out.replace(/@[A-Za-z0-9-]+ \((owner|maintainer|contributor)\)/g, 'the $1');
    out = out.replace(/\b[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+#\d+\b/g, 'a member repository');
