// where the file has none.
export function withBody(source, body) {
  const src = String(source ?? '');
  if (!src.startsWith('---')) return `---\nmetadata:\n  body: ${body}\n---\n${src}`;
  const end = src.indexOf('\n---', 3);
  if (end === -1) return src;
  const lines = src.slice(4, end).split('\n');
