+
+// --- the carriers ------------------------------------------------------------------
+
+// The top-level rule bullets of a prose file: `- **lead-in** …` and every line that
+// belongs to it (continuation, sub-bullets, blank lines inside the block), closed by
+// the next top-level bullet or a heading. The marker, when present, ends the block's
+// last non-blank line; `lastLine` is that line's index for the writer that appends
+// one. `numeric` is the retired numeric marker, read only so the conversion can
+// replace it. Indices are 0-based.
+export function ruleBlocks(text) {
+  const lines = String(text ?? '').split('\n');
+  const blocks = [];
+  let cur = null;
+  const close = () => {
+    if (!cur) return;
+    let end = cur.end;
