+    read: (p) => (removed.has(p) ? null : written.has(p) ? written.get(p) : base.read(p)),
+    write: (p, t) => { written.set(p, t); removed.delete(p); },
+    remove: (p) => { removed.add(p); written.delete(p); },
+    listDir,
+  };
