+    lines.push(log.trim() || '(none)');
+    note(log);
+  }
+  lines.push('\n## pull requests those commits name');
+  lines.push(prs.size ? [...prs].sort((a, b) => a - b).map((n) => `#${n}`).join(' ') : '(none)');
