+  if (versions) {
+    lines.push('\n## VERSIONS.md rows naming them');
+    const rows = versions.split('\n').filter((l) => l.startsWith('|') && [...prs].some((n) => l.includes(`#${n}`)));
+    lines.push(rows.join('\n') || '(none)');
+  }
