+    assert.equal(readFileSync(join(root, '.claudinite/local/packs/mine/RULES.md'), 'utf8'), FILES['.claudinite/local/packs/mine/RULES.md']);
+    assert.ok(!existsSync(join(root, '.claudinite/local/packs/mine/provenance')));
