22	export { PROVENANCE_DIR };
23	
24	// The pack's own file and the declined log, each sorted ahead of every element by
25	// the underscore. `_pack` is also the id the manifest names.
26	export const PACK_ELEMENT = '_pack';
27	export const DECLINED_FILE = '_declined.md';
28	
29	// The closed kind vocabulary, and the kinds whose entry always carries Mechanism.
30	export const KINDS = Object.freeze(['born', 'reworded', 'strengthened', 'weakened', 'split', 'merged', 'moved',
31	  'converted', 'trigger-changed', 'policy-changed', 'severity-changed', 'reaffirmed', 'promoted', 'retired']);
32	export const MECHANISM_KINDS = Object.freeze(['born', 'converted', 'moved', 'trigger-changed', 'policy-changed', 'severity-changed']);
33	export const FIELDS = Object.freeze(['Source', 'Reason', 'Actor', 'Model', 'Mechanism', 'Rejected', 'Retire when', 'Landed']);
34	export const DECLINED_KIND = 'declined';
35	
36	// A slug marker ends a rule's last line: two to four hyphenated words, so a plain
37	// parenthetical (`(canon)`, `(see below)`), an issue (`(#1119)`) and the retired
38	// numeric marker (`(3)`, `(3, 7)`) never read as one.
39	export const SLUG_RE = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)+$/;
40	const MARKER_AT_END = /\s*\(([a-z][a-z0-9]*(?:-[a-z0-9]+)+)\)\s*$/;
41	// The numeric marker the references convention used, read only so the conversion
42	// can replace it.
43	const NUMERIC_MARKER_AT_END = /\s*\((\d+(?:\s*,\s*\d+)*)\)\s*$/;
44	
45	const RULE_BULLET = /^- \*\*/;
46	const TOP_BULLET = /^- /;
47	const NESTED_ITEM = /^\s+(?:[-*+]|\d+\.)\s/;
