50	const ENTRY_HEAD = /^## (\d{4}-\d{2}-\d{2}) · ([a-z-]+) · (.+?)\s*$/;
51	const FIELD_LINE = /^- \*\*([A-Z][A-Za-z ]*?):\*\*\s*(.*)$/;
52	
53	// A check's id becomes a file name with its slash as a hyphen (`cer/x` → `cer-x.md`).
54	export const elementIdOf = (id) => String(id).replace(/\//g, '-');
55	export const fileOfId = (id) => `${elementIdOf(id)}.md`;
56	export const idOfFile = (name) => name.replace(/\.md$/, '');
57	
58	// --- the file grammar --------------------------------------------------------------
59	
60	// Every entry of a provenance file, in file order, with its fields and the grammar
61	// faults found on the way. A file is its entries and nothing else: a header, front
62	// matter or prose outside an entry is a fault, since it is the one part of the file
63	// that invites editing. `kinds` is the vocabulary the file admits — the element
64	// kinds, or the declined log's one kind.
65	export function parseEntries(text, { kinds = KINDS } = {}) {
66	  const entries = [];
67	  const errors = [];
68	  const lines = String(text ?? '').split('\n');
69	  let current = null;
70	  let lastDate = '';
71	  lines.forEach((raw, i) => {
72	    const line = raw.replace(/\r$/, '');
73	    const n = i + 1;
74	    const head = ENTRY_HEAD.exec(line);
75	    if (head) {
76	      const [, date, kind, title] = head;
77	      if (!kinds.includes(kind)) errors.push({ line: n, what: `entry kind "${kind}" is not in the vocabulary` });
78	      if (Number.isNaN(Date.parse(`${date}T00:00:00Z`))) errors.push({ line: n, what: `entry date "${date}" is not a date` });
79	      else if (date < lastDate) errors.push({ line: n, what: `entry dated ${date} follows one dated ${lastDate}; entries are appended in date order` });
80	      lastDate = date > lastDate ? date : lastDate;
81	      current = { date, kind, title, line: n, fields: {}, order: [], last: null };
82	      entries.push(current);
83	      return;
84	    }
85	    if (line.startsWith('## ')) {
86	      errors.push({ line: n, what: 'entry heading does not read "## <YYYY-MM-DD> · <kind> · <one line>"' });
87	      current = null;
88	      return;
89	    }
90	    if (!line.trim()) return;
91	    if (!current) {
92	      errors.push({ line: n, what: 'text outside an entry — a file is its entries and nothing else' });
93	      return;
94	    }
95	    const field = FIELD_LINE.exec(line);
96	    if (field) {
97	      const [, name, value] = field;
98	      if (!FIELDS.includes(name)) errors.push({ line: n, what: `field "${name}" is not in the vocabulary (${FIELDS.join(', ')})` });
99	      if (!value.trim()) errors.push({ line: n, what: `field "${name}" is empty — a field with nothing behind it is omitted, never filled` });
100	      if (name in current.fields) errors.push({ line: n, what: `field "${name}" repeats within one entry` });
101	      current.fields[name] = value.trim();
102	      current.order.push(name);
103	      current.last = name;
104	      return;
105	    }
106	    if (/^\s{2,}\S/.test(line) && current.last) {
107	      current.fields[current.last] = `${current.fields[current.last]} ${line.trim()}`;
