import("./engine/checks/helpers/provenance.mjs").then(({ checkoutIo, skillShape }) => {
  const fs = require("fs");
  const io = checkoutIo(process.cwd());
  const rows = [];
  for (const root of ["packs", ".claudinite/local/packs"]) for (const pack of fs.readdirSync(root)) {
    const sk = `${root}/${pack}/skills`;
    if (!fs.existsSync(sk) || !fs.statSync(sk).isDirectory()) continue;
    for (const name of fs.readdirSync(sk)) {
      const f = `${sk}/${name}/SKILL.md`;
      if (!fs.existsSync(f)) continue;
      const s = skillShape(fs.readFileSync(f, "utf8"));
      const steps = s.bullets.length ? (fs.readFileSync(f, "utf8").split("\n").filter((l) => /^\d+\.\s/.test(l)).length) : 0;
      rows.push(`${(s.body ?? "-").padEnd(10)} ${s.proposed.padEnd(10)} b=${String(s.bullets.length).padStart(2)} n=${String(steps).padStart(2)}  ${pack}/${name}  :: ${s.bullets.slice(0, 3).map((b) => b.trigger.slice(0, 28)).join(" | ")}`);
    }
  }
  console.log(rows.sort().join("\n"));
});
'

