+    named.add(id);
+    const f = files.get(id);
+    if (!f || f.status !== 'live') out.dangling.push({ ...at, id, carrier, retired: !!f });
+  };
+  for (const r of carriers.rules) {
+    if (!r.slug) out.unmarked.push({ file: r.file, line: r.line, trigger: r.trigger });
