+  }
+  for (const g of carriers.guidelines) {
+    if (!g.slug) out.unmarked.push({ file: g.file, line: g.line, trigger: g.trigger });
+    else name(g.slug, `guideline "${g.trigger}"`, { file: g.file, line: g.lastLine });
