+      if (!kinds.includes(kind)) errors.push({ line: n, what: `entry kind "${kind}" is not in the vocabulary` });
+      if (Number.isNaN(Date.parse(`${date}T00:00:00Z`))) errors.push({ line: n, what: `entry date "${date}" is not a date` });
