import re, pathlib
p = pathlib.Path('engine-tests/rule-index.mjs')
t = p.read_text()
old = """// The marker that ends a rule and names its provenance file is an id, not prose: it
// is not counted, so marking a rule never moves its band.
const PROVENANCE_MARKER = /\\s*\\([a-z][a-z0-9]*(?:-[a-z0-9]+)+\\)\\s*$/;
const wordsIn = (lines) => lines.join('\\n').replace(PROVENANCE_MARKER, '').split(/\\s+/).filter(Boolean).length;
"""
new = """// The marker that ends a rule and names its provenance file is an id, not prose: it
// is not counted, so marking a rule never moves its band. It ends the rule's lead
// paragraph, which a nested list or a fenced block may follow, so it is read at any
// line's end and not only the block's.
const PROVENANCE_MARKER = /\\s*\\([a-z][a-z0-9]*(?:-[a-z0-9]+)+\\)\\s*$/gm;
const wordsIn = (lines) => lines.join('\\n').replace(PROVENANCE_MARKER, '').split(/\\s+/).filter(Boolean).length;
"""
assert old in t
p.write_text(t.replace(old, new))
r = pathlib.Path('packs/claudinite-lifecycle/README.md')
rt = r.read_text()
old_row = "| A silent check run is clean | low | complexity | prose: <100 words |"
assert old_row in rt
r.write_text(rt.replace(old_row, "| A silent check run is clean | low | complexity | prose: <50 words |"))
print("ok")
EOF
